// Escalating windows. Anything already expired is reported every single day.
const rows = $input.all().map(i => i.json).filter(r => r.Item && r.Expires);
const today = new Date(); today.setHours(0,0,0,0);

const buckets = { expired: [], week: [], month: [], quarter: [] };

for (const r of rows) {
  const exp = new Date(r.Expires); exp.setHours(0,0,0,0);
  if (isNaN(exp)) continue;
  const days = Math.floor((exp - today) / 864e5);

  const entry = {
    item: r.Item, type: r.Type || '', holder: r.Holder || 'the business',
    expires: r.Expires, days,
    contact: r.RenewalContact || '', notes: r.Notes || ''
  };

  if (days < 0)        buckets.expired.push({ ...entry, days_overdue: Math.abs(days) });
  else if (days <= 7)  buckets.week.push(entry);
  else if (days <= 30) buckets.month.push(entry);
  else if (days <= 90) buckets.quarter.push(entry);
}

const line = e => `• ${e.item}${e.holder && e.holder !== 'the business' ? ' (' + e.holder + ')' : ''} — ${e.expires}${e.contact ? '  · renew via ' + e.contact : ''}`;

// only send an email at all if something needs saying
const anything = buckets.expired.length || buckets.week.length || buckets.month.length || buckets.quarter.length;
// the quarterly bucket is only worth mentioning on Mondays, so it doesn't become daily noise
const isMonday = today.getDay() === 1;

return [{ json: {
  anything, isMonday,
  counts: { expired: buckets.expired.length, week: buckets.week.length,
            month: buckets.month.length, quarter: buckets.quarter.length },
  expired_txt: buckets.expired.map(e => `• ${e.item}${e.holder !== 'the business' ? ' (' + e.holder + ')' : ''} — EXPIRED ${e.days_overdue} days ago${e.contact ? '  · ' + e.contact : ''}`).join('\n'),
  week_txt:    buckets.week.map(line).join('\n'),
  month_txt:   buckets.month.map(line).join('\n'),
  quarter_txt: buckets.quarter.map(line).join('\n'),
  worst: buckets.expired.length ? 'EXPIRED'
       : buckets.week.length ? 'THIS WEEK'
       : buckets.month.length ? 'this month' : 'ok'
}}];

